from textual.app import ComposeResult, on
from textual.containers import Horizontal
from textual.widgets import Header, Footer, Tree, TextArea
from textual.app import App
import os


class DirectoryExplorer(App):
    """A Textual app with a directory tree on the left and text area on the right."""

    BINDINGS = [("d", "toggle_dark", "Toggle dark mode")]

    def compose(self) -> ComposeResult:
        yield Header()
        with Horizontal():
            yield Tree(".", id="directory_tree")
            yield TextArea(id="text_area")
        yield Footer()

    def on_mount(self) -> None:
        tree = self.query_one("#directory_tree", Tree)
        tree.root.expand()
        self._load_directory(tree.root, ".")

    def _load_directory(self, node, path: str) -> None:
        """Recursively load directory structure."""
        try:
            entries = sorted(os.listdir(path))
            for entry in entries:
                if entry.startswith('.'):
                    continue
                full_path = os.path.join(path, entry)
                if os.path.isdir(full_path):
                    child = node.add(entry, expand=False)
                    self._load_directory(child, full_path)
                else:
                    node.add(entry)
        except (PermissionError, OSError):
            pass

    @on(Tree.NodeSelected)
    def handle_tree_selection(self, event: Tree.NodeSelected) -> None:
        """Handle file selection in tree."""
        text_area = self.query_one("#text_area", TextArea)

        path_parts = []
        node = event.node
        while node != node.tree.root:
            path_parts.insert(0, str(node.label))
            node = node.parent
        path_parts.insert(0, ".")
        full_path = os.path.join(*path_parts)

        if os.path.isfile(full_path):
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    text_area.text = f.read()
            except (UnicodeDecodeError, IOError):
                text_area.text = "[Unable to read file]"

    def action_toggle_dark(self) -> None:
        """Toggle dark mode."""
        self.dark = not self.dark


if __name__ == "__main__":
    app = DirectoryExplorer()
    app.run()

